package com.gymmind.ai.domain; import java.util.*; public final class RrfFusion { private static final double K=60d; private RrfFusion(){} public static List<RankedChunk> merge(List<RankedChunk> keyword,List<RankedChunk> vector,int limit){Map<String,Double> scores=new HashMap<>();Map<String,Integer> best=new HashMap<>();List<RankedChunk> first=keyword==null?Collections.emptyList():keyword;List<RankedChunk> second=vector==null?Collections.emptyList():vector;for(List<RankedChunk> route:List.of(first,second))for(RankedChunk c:route){scores.merge(c.id(),1d/(K+c.rank()),Double::sum);best.merge(c.id(),c.rank(),Math::min);}return scores.keySet().stream().sorted(Comparator.<String>comparingDouble(scores::get).reversed().thenComparingInt(best::get).thenComparing(String::compareTo)).limit(limit).map(id->new RankedChunk(id,best.get(id))).toList();} }
